import { live, demo } from './api.js';
import { escapeHTML as e, money, number, shortMoney, date, periodDates, csv, labels } from './utils.js';

const paths={
  chef:'M8 16C2 16 2 7 8 7c0-7 10-7 10 0 6 0 6 9 0 9v6H8z M9 18h8',
  dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  stores:'M3 10h18L19 3H5z M4 10v11h16V10 M9 21v-7h6v7 M3 10c0 4 4 4 5 0 1 4 6 4 7 0 1 4 6 4 6 0',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',
  products:'M12 3 3 8v9l9 5 9-5V8z M3 8l9 5 9-5 M12 13v9 M7.5 5.5l9 5',
  orders:'M8 4H5v18h14V4h-3 M8 2h8v5H8z M8 12h8 M8 16h5',
  transactions:'M3 5h18v14H3z M3 9h18 M7 14h3 M16 14h2',
  drivers:'M3 17h2 M19 17h2V9h-6v8H9 M3 17V4h12v13 M17 9V6h2l3 5 M9 17a3 3 0 1 0-6 0 3 3 0 0 0 6 0 M21 17a3 3 0 1 0-6 0 3 3 0 0 0 6 0',
  reports:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',
  settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 2h4l1 3 3-1 3 3-1 3 3 1v4l-3 1 1 3-3 3-3-1-1 3h-4l-1-3-3 1-3-3 1-3-3-1v-4l3-1-1-3 3-3 3 1z',
  arrow:'M5 12h14 M13 6l6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',
  refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 3 M18 18a8 8 0 0 1-13-3',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
  search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
  close:'m6 6 12 12 M18 6 6 18',menu:'M3 6h18 M3 12h18 M3 18h18',
  lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',
  logout:'M9 3H4v18h5 M9 12h13 M17 7l5 5-5 5',
  download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',
  check:'m5 12 4 4 10-10',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',
  info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',
  help:'M9 8a3 3 0 0 1 6 1c0 2-3 2-3 5 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
};
const icon=(name,size=18)=>`<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const brand=()=>`<div class="brand"><span class="brand-mark">${icon('chef',38)}</span><div><div class="brand-name">Rasa<span>Lokal</span></div><div class="brand-label">ADMIN MARKETPLACE</div></div></div>`;
const nav=[['dashboard','Dashboard'],['stores','Data UMKM'],['users','Data Pengguna'],['products','Produk'],['orders','Pesanan'],['transactions','Transaksi'],['drivers','Driver'],['reports','Laporan'],['settings','Pengaturan']];
const descriptions={dashboard:'Pantau aktivitas dan perkembangan marketplace Anda.',stores:'Kelola usaha lokal yang tergabung di RasaLokal.',users:'Lihat akun dan peran pengguna di marketplace.',products:'Pantau katalog dan ketersediaan produk UMKM.',orders:'Pantau pesanan dari toko hingga sampai ke pembeli.',transactions:'Tinjau pembayaran dan nilai transaksi pesanan.',drivers:'Verifikasi pendaftaran dan kelola akses driver.',reports:'Unduh laporan untuk kebutuhan operasional Anda.',settings:'Kelola sesi admin dan lihat panduan akses.'};
const filters={stores:['open','closed','suspended'],users:['customer','seller','driver','admin'],products:['available','unavailable','blocked','suspended'],orders:['pending_payment','confirmed','preparing','ready_for_pickup','driver_assigned','driver_going_to_customer','completed','cancelled'],transactions:['review','pending','processing','success','failed'],drivers:['pending','active','busy'],audit:[]};
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let mode='',user=null,period='year',current='dashboard',requestVersion=0,tableVersion=0,search='',status='',offset=0,cache=new Map(),snapshot=null,subscription=null,busy=false;
const api=()=>mode==='demo'?demo:live;
const label=value=>labels[value]||value||'—';
const initials=value=>String(value||'R').split(/[ @]/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const badge=value=>{const color=['open','available','active','success','completed','delivered'].includes(value)?'green':['pending','pending_payment','ready_for_pickup','preparing','confirmed','merchant_accepted'].includes(value)?'orange':['blocked','suspended','cancelled','rejected','failed','payment_failed'].includes(value)?'red':['closed','unavailable'].includes(value)?'gray':'';return `<span class="badge ${color}">${e(label(value))}</span>`;};
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
const loading=()=>'<div class="loading" role="status"><span class="spinner"></span>Memuat data…</div>';
function empty(title='Belum ada data',text='Data akan muncul di sini setelah ada aktivitas di marketplace.'){return `<div class="empty"><div class="empty-icon">${icon('products',25)}</div><strong>${e(title)}</strong><p>${e(text)}</p></div>`;}
function remember(rows,kind){rows.forEach(r=>cache.set(`${kind}:${r.id}`,r));return rows;}
function showLogin(error=''){
  mode='';user=null;snapshot=null;requestVersion++;cache.clear();subscription?.unsubscribe();subscription=null;
  app.innerHTML=`<main id="main" class="login-layout"><section class="login-brand">${brand()}<div class="login-hero"><div class="eyebrow">RUANG TUMBUH USAHA LOKAL</div><h1>Satu tempat.<br>Semua aktivitas<br><em>RasaLokal.</em></h1><p>Pantau usaha, pesanan, dan perjalanan driver. Bantu UMKM lokal melangkah lebih jauh setiap hari.</p><div class="login-decoration"><div class="login-feature">${icon('stores',23)}Kelola UMKM</div><div class="login-feature">${icon('orders',23)}Pantau pesanan</div><div class="login-feature">${icon('drivers',23)}Aktivasi driver</div></div></div><div class="login-copyright">© ${new Date().getFullYear()} RasaLokal · Kuliner lokal, UMKM naik kelas.</div></section><section class="login-main"><div class="login-form"><div class="login-symbol">${icon('lock',23)}</div><h1>Selamat datang kembali</h1><p class="subtext">Masuk dengan akun admin untuk mengelola marketplace RasaLokal.</p><div id="login-error" ${error?'':'hidden'} class="login-error" role="alert">${e(error)}</div><form id="login-form"><label class="form-field">Email admin<input type="email" name="email" autocomplete="username" placeholder="nama@email.com" required maxlength="254"></label><label class="form-field">Kata sandi<div class="password-wrap"><input type="password" name="password" autocomplete="current-password" placeholder="Masukkan kata sandi" required><button type="button" class="icon-button" data-action="show-password" aria-label="Tampilkan kata sandi">${icon('eye',18)}</button></div></label><button class="button primary full" type="submit">Masuk ke dashboard ${icon('arrow',16)}</button></form><div class="login-note">${icon('shield',13)}Akses khusus admin yang telah diaktifkan</div><div class="login-divider">INGIN MELIHAT TAMPILANNYA?</div><button class="button full" data-action="demo">Lihat contoh dashboard ${icon('arrow',15)}</button><p class="login-demo-caption">Jelajahi fitur menggunakan data contoh.</p><p class="login-help">Akun admin belum aktif? <button data-action="guide">Lihat panduan akses</button></p></div></section></main>`;
}
async function enterLive(session){
  if(!session)return showLogin();
  if(!await live.authorized())return showLogin('Akun ini belum memiliki akses admin. Pemilik proyek perlu mengaktifkannya terlebih dahulu.');
  user=session.user;mode='live';sessionStorage.removeItem('rasalokal-admin-demo');subscription?.unsubscribe();subscription=live.onLogout(()=>{if(mode==='live')showLogin('Sesi berakhir. Silakan masuk kembali.');});renderShell();await route();
}
function renderShell(){
  const adminName=mode==='demo'?'Admin RasaLokal':(user?.email?.split('@')[0]||'Admin');
  app.innerHTML=`<aside class="sidebar" aria-label="Menu utama">${brand()}<div class="nav-caption">MENU UTAMA</div><nav class="nav">${nav.slice(0,8).map(([id,title])=>`<a class="nav-link" href="#${id}" data-nav="${id}">${icon(id,18)}<span>${title}</span>${id==='drivers'?'<span id="driver-count" class="count" hidden></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><a class="nav-link" href="#settings" data-nav="settings">${icon('settings',18)}<span>Pengaturan</span></a><button class="nav-link" data-action="logout">${icon('logout',18)}<span>${mode==='demo'?'Keluar dari contoh':'Keluar'}</span></button></nav><div class="sidebar-help">${icon('help',19)}<strong>Perlu bantuan akses?</strong><span>Mulai dari panduan admin RasaLokal.</span><a href="#settings" data-nav="settings">Buka panduan ${icon('arrow',13)}</a></div><div class="sidebar-foot"><span>RasaLokal Admin</span><span>v1.0</span></div></div></aside><button class="overlay" data-action="close-menu" aria-label="Tutup menu"></button><div class="shell"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Buka menu" aria-expanded="false">${icon('menu',20)}</button><div class="breadcrumb"><span>Marketplace</span>${icon('chevron',12)}<strong id="breadcrumb-title">Dashboard</strong></div><div class="top-actions"><span class="today">${e(new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date()))}</span><button class="icon-button" data-action="pending-drivers" aria-label="Lihat pendaftaran driver">${icon('bell',20)}<span class="notification-dot" id="notification-dot" hidden></span></button><span class="top-divider"></span><button class="account" data-nav="settings" aria-label="Pengaturan akun admin"><span class="avatar">${e(initials(adminName))}</span><span><strong>${e(adminName)}</strong><small>Administrator</small></span>${icon('down',13)}</button></div></header><main id="main" class="page" tabindex="-1"><div id="content">${loading()}</div></main></div>`;
}
function demoBanner(){return mode==='demo'?`<div class="demo-banner">${icon('info',16)}<span><strong>Mode contoh.</strong> Anda sedang melihat data simulasi RasaLokal.</span><button class="button" data-action="logout">Masuk sebagai admin ${icon('arrow',12)}</button></div>`:'';}
function heading(){return `${demoBanner()}<div class="page-heading"><div><div class="eyebrow">RASALOKAL MARKETPLACE</div><h1>${e(nav.find(n=>n[0]===current)?.[1]||'Dashboard')}</h1><p class="subtext">${e(descriptions[current]||'')}</p></div><div class="heading-actions">${['dashboard','orders','transactions','reports'].includes(current)?`${icon('calendar',16)}<select class="select" id="period" aria-label="Periode laporan">${[['year','Tahun ini'],['7','7 hari terakhir'],['30','30 hari terakhir'],['90','90 hari terakhir']].map(([v,t])=>`<option value="${v}" ${period===v?'selected':''}>${t}</option>`).join('')}</select>`:''}<button class="button" data-action="refresh" aria-label="Perbarui data">${icon('refresh',15)}<span>Perbarui</span></button></div></div>`;}
function footer(){const at=snapshot?.updated_at;return `<footer class="footer"><span>© ${new Date().getFullYear()} RasaLokal. Kuliner lokal, UMKM naik kelas.</span><span>${icon(mode==='demo'?'info':'clock',11)}${mode==='demo'?'Data contoh':at?'Diperbarui '+new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date(at))+' WIB':'Supabase · RasaLokal'}</span></footer>`;}
async function route(){
  if(!mode)return;
  const candidate=location.hash.slice(1).split('?')[0];current=nav.some(n=>n[0]===candidate)?candidate:'dashboard';
  const version=++requestVersion;tableVersion++;cache.clear();offset=0;
  document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.mobile-menu')?.setAttribute('aria-expanded','false');
  document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===current;el.classList.toggle('active',active);active?el.setAttribute('aria-current','page'):el.removeAttribute('aria-current');});
  document.querySelector('#breadcrumb-title').textContent=nav.find(n=>n[0]===current)[1];document.title=`${nav.find(n=>n[0]===current)[1]} — RasaLokal Admin`;
  const content=document.querySelector('#content');content.innerHTML=heading()+loading();
  try{
    if(current==='settings'){content.innerHTML=heading()+settings()+footer();return;}
    if(current==='dashboard'||current==='reports'){
      const results=await Promise.all([api().snapshot(period),...(current==='dashboard'?[api().list('stores',{limit:4}),api().list('orders',{limit:4,period})]:[])]);
      if(version!==requestVersion)return;snapshot=results[0];updateBadges();
      content.innerHTML=heading()+(current==='dashboard'?dashboard(snapshot,remember(results[1].rows,'stores'),remember(results[2].rows,'orders')):reports(snapshot))+footer();
    }else{content.innerHTML=heading()+listCard()+footer();await loadTable(version);}
  }catch(error){if(version===requestVersion)content.innerHTML=heading()+`<div class="card">${empty('Data belum dapat dimuat',error.message)}<div style="text-align:center;padding:0 20px 25px"><button class="button primary" data-action="refresh">Coba lagi</button> <button class="button" data-action="guide">Panduan akses</button></div></div>`;}
}
function updateBadges(){const count=document.querySelector('#driver-count'),dot=document.querySelector('#notification-dot');if(count){count.textContent=snapshot?.pending_drivers||'';count.hidden=!snapshot?.pending_drivers;}if(dot)dot.hidden=!snapshot?.pending_drivers;}
function stats(data,report=false){return `<div class="stats">${[
  [report?'Pesanan selesai':'Total UMKM',report?data.completed_orders:data.stores,report?'orders':'stores','',report?'Selesai pada periode terpilih':`${number(data.active_stores)} UMKM tidak ditangguhkan`],
  [report?'Biaya layanan':'Total pengguna',report?money(data.service_fees):data.users,report?'transactions':'users','cyan',report?'Dari pesanan berstatus lunas':'Akun terdaftar di RasaLokal'],
  ['Total pesanan',data.orders,'orders','orange','Pada periode yang dipilih'],
  ['Nilai transaksi',money(data.paid_amount),'reports','green','Total pembayaran berstatus lunas']
].map(([title,value,i,color,note])=>`<article class="stat"><div class="stat-top"><span class="stat-label">${title}</span><span class="stat-icon ${color}">${icon(i,18)}</span></div><div class="stat-value mono" style="${String(value).length>14?'font-size:23px':''}">${typeof value==='number'?number(value):e(value)}</div><div class="stat-note"><span class="tiny-dot"></span>${e(note)}</div></article>`).join('')}</div>`;}
function chart(data){
  const rows=data.chart||[],max=Math.max(...rows.map(r=>Number(r.amount)),1),axis=Math.ceil(max/4/10000)*10000||10000,ceiling=axis*4;
  const title=r=>new Intl.DateTimeFormat('id-ID',{month:'short',...(data.bucket==='month'?{}:{day:'numeric'}),timeZone:'UTC'}).format(new Date(r.date+'T00:00:00Z'));
  return `<section class="card"><div class="card-head"><div><h2>Grafik transaksi</h2><p class="subtext">Perkembangan nilai transaksi marketplace</p></div><span class="legend">Pembayaran lunas</span></div><div class="chart-summary"><strong class="mono">${money(data.paid_amount)}</strong><span>pada periode terpilih</span></div><div class="chart-wrap" role="group" aria-label="Grafik nilai transaksi berstatus lunas"><div class="chart-grid">${[4,3,2,1,0].map(v=>`<div><span>${v?shortMoney(v*axis):'0'}</span></div>`).join('')}</div><div class="bars">${rows.map(r=>`<div class="bar-slot"><button class="bar" style="height:${(Number(r.amount)===0?0:Math.max(Number(r.amount)/ceiling*100,1))}%" title="${e(title(r))}: ${money(r.amount)} · ${number(r.orders)} pesanan" aria-label="${e(title(r))}, ${money(r.amount)}, ${number(r.orders)} pesanan"></button></div>`).join('')}</div><div class="bar-labels">${rows.map((r,i)=>`<span>${rows.length>12&&i%Math.ceil(rows.length/10)!==0?'':e(title(r))}</span>`).join('')}</div></div><p class="chart-note">Berdasarkan tanggal pesanan (WIB). Nilai transaksi mencakup total pembayaran pembeli.</p></section>`;
}
function dashboard(data,stores,orders){return `${stats(data)}<div class="dashboard-middle">${chart(data)}<section class="card queue-card"><div class="card-head"><div><h2>Perlu ditindaklanjuti</h2><p class="subtext">Antrean operasional marketplace</p></div></div><div class="queue-list">${[
  ['drivers','Driver menunggu','Tinjau dan aktifkan akun',data.pending_drivers,'','pending-drivers'],
  ['transactions','Verifikasi pembayaran','Periksa dana yang diterima',data.pending_payments,'blue','pending-payments'],
  ['orders','Siap dijemput','Tugaskan driver tersedia',data.ready_orders,'green','ready-orders']
].map(([i,title,text,count,color,action])=>`<button class="queue-item" data-action="${action}"><span class="queue-icon ${color}">${icon(i,18)}</span><span class="queue-text">${title}<small>${text}</small></span><span class="queue-number">${number(count)}</span>${icon('chevron',13)}</button>`).join('')}</div><div class="queue-foot">${icon('shield',14)}Setiap perubahan admin tercatat otomatis.</div></section></div><div class="dashboard-tables"><section class="card"><div class="card-head"><h2>UMKM terbaru</h2><a href="#stores" class="button link" data-nav="stores">Lihat semua ${icon('arrow',13)}</a></div>${table('stores',stores,true)}</section><section class="card"><div class="card-head"><h2>Pesanan terbaru</h2><a href="#orders" class="button link" data-nav="orders">Lihat semua ${icon('arrow',13)}</a></div>${table('orders',orders,true)}</section></div>`;}
function person(row,kind,index){return `<button class="table-link" data-detail="${kind}" data-id="${e(row.id)}"><span class="cell-person"><span class="avatar ${['','blue','green','purple'][index%4]}">${kind==='stores'?icon('stores',16):e(initials(row.name))}</span><span><strong>${e(label(row.name))}</strong><small>${e(kind==='orders'||kind==='transactions'?'#'+row.id.slice(0,8).toUpperCase():row.secondary||row.email||'—')}</small></span></span></button>`;}
function table(kind,rows,compact=false){
  if(!rows.length)return empty(search||status?'Data tidak ditemukan':'Belum ada data',search||status?'Coba kata kunci atau filter lain.':'Aktivitas marketplace akan tampil di sini.');
  const heads=kind==='stores'?['Nama UMKM',compact?'Lokasi':'Pemilik',...(!compact?['Produk']:[]),'Status']:kind==='users'?['Pengguna','Email','Peran','Bergabung']:kind==='products'?['Produk','Kategori','Harga','Status']:kind==='drivers'?['Driver','Kontak','Status',...(!compact?['Bergabung']:[])]:kind==='audit'?['Aktivitas','Admin','Waktu']:['Pembeli',...(compact?[]:['UMKM']),'Total',kind==='transactions'?'Pembayaran':'Status'];
  return `<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}${!compact?'<th scope="col"><span class="muted">Detail</span></th>':''}</tr></thead><tbody>${rows.map((r,i)=>`<tr>${kind==='audit'?`<td>${e(label(r.name))}</td><td>${e(r.secondary)}</td><td>${date(r.created_at)}</td>`:`<td>${person(r,kind,i)}</td>`}${kind==='stores'?`<td>${e((compact?r.address:r.secondary)||'—')}</td>${!compact?`<td>${number(r.products)}</td>`:''}<td>${badge(r.status)}</td>`:kind==='users'?`<td>${e(r.email||'—')}</td><td>${badge(r.status)}</td><td>${date(r.created_at)}</td>`:kind==='products'?`<td>${e(r.category)}</td><td class="mono">${money(r.amount)}</td><td>${badge(r.status)}</td>`:kind==='drivers'?`<td>${e(r.phone||r.email||'—')}</td><td>${badge(r.status)}</td>${!compact?`<td>${date(r.created_at)}</td>`:''}`:kind==='audit'?'':`${!compact?`<td>${e(r.secondary)}</td>`:''}<td class="mono" style="font-weight:600">${money(r.amount)}</td><td>${badge(kind==='transactions'?r.payment_status:r.status)}</td>`}${!compact?`<td><button class="table-action" data-detail="${kind}" data-id="${e(r.id)}">${kind==='drivers'&&!r.active?'Tinjau':'Lihat'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;
}
function listCard(){return `<section class="card list-card"><div class="toolbar"><label class="searchbox">${icon('search',16)}<input id="search" type="search" placeholder="Cari ${e(nav.find(n=>n[0]===current)[1].toLowerCase())}…" value="${e(search)}" maxlength="200" aria-label="Cari data"></label><select id="status" class="select" aria-label="Filter status"><option value="">Semua ${current==='users'?'peran':'status'}</option>${(filters[current]||[]).map(f=>`<option value="${f}" ${status===f?'selected':''}>${e(label(f))}</option>`).join('')}</select><span class="toolbar-count" id="table-count"></span>${['orders','transactions'].includes(current)?`<button class="button" data-export="${current}">${icon('download',14)}Ekspor CSV</button>`:''}</div><div id="table-content">${loading()}</div></section>`;}
async function loadTable(version=requestVersion){const own=++tableVersion,target=document.querySelector('#table-content');if(!target)return;target.innerHTML=loading();try{const result=await api().list(current,{search,status,offset,period});if(version!==requestVersion||own!==tableVersion)return;remember(result.rows,current);document.querySelector('#table-count').textContent=`${number(result.total)} data`;target.innerHTML=table(current,result.rows)+`<div class="pagination"><span>${result.total?`${offset+1}–${Math.min(offset+10,result.total)} dari ${number(result.total)}`:'0 data'}</span><div class="pagination-actions"><button class="button" data-action="previous" ${offset===0?'disabled':''}>Sebelumnya</button><button class="button" data-action="next" ${offset+10>=result.total?'disabled':''}>Berikutnya</button></div></div>`;}catch(error){if(version===requestVersion&&own===tableVersion)target.innerHTML=empty('Data belum dapat dimuat',error.message);}}
function reports(data){const {start,end}=periodDates(period);return `${stats(data,true)}<div class="dashboard-middle">${chart(data)}<section class="card report-card"><span class="stat-icon green">${icon('reports',20)}</span><h2>Ringkasan periode</h2><p>${date(start)} – ${date(end)}</p><div class="settings-row"><span>Pesanan</span><strong>${number(data.orders)}</strong></div><div class="settings-row"><span>Selesai</span><strong>${number(data.completed_orders)}</strong></div><div class="settings-row"><span>Biaya layanan lunas</span><strong>${money(data.service_fees)}</strong></div><p class="period-note">Biaya layanan dan nilai transaksi dihitung dari pesanan berstatus pembayaran lunas dalam periode terpilih.</p></section></div><div class="report-grid">${[['orders','Laporan pesanan','Rincian pesanan, toko, pembeli, dan status pengiriman.'],['transactions','Laporan transaksi','Nilai pembayaran, metode, dan status transaksi.']].map(([kind,title,desc])=>`<section class="card report-card"><span class="stat-icon">${icon(kind,20)}</span><h2>${title}</h2><p>${desc}</p><button class="button" data-export="${kind}">${icon('download',16)}Unduh CSV</button></section>`).join('')}</div>`;}
function settings(){return `<div class="settings-grid"><section class="card"><div class="card-head"><h2>Akun administrator</h2>${icon('shield',20)}</div><div class="settings-content"><div class="settings-row"><span>Email</span><strong>${e(mode==='demo'?'admin@contoh.id':user?.email)}</strong></div><div class="settings-row"><span>Hak akses</span><strong>${mode==='demo'?'Pratinjau data contoh':'Admin marketplace'}</strong></div><div class="settings-row"><span>Sumber data</span><strong>${mode==='demo'?'Simulasi lokal':'Supabase RasaLokal'}</strong></div><div class="settings-row"><span>Zona waktu laporan</span><strong>WIB · Asia/Jakarta</strong></div><button class="button" data-action="logout">${icon('logout',15)}${mode==='demo'?'Masuk dengan akun admin':'Keluar dari akun'}</button></div></section><section class="card"><div class="card-head"><h2>Aktivasi dan akses</h2>${icon('lock',18)}</div><div class="settings-content"><p>Akun admin diaktifkan oleh pemilik proyek Supabase. Driver mendaftar melalui aplikasi RasaLokal, lalu menunggu persetujuan di menu Driver.</p><ol><li>Periksa nama, kontak, dan kendaraan driver.</li><li>Aktifkan akun setelah data terverifikasi.</li><li>Buka pesanan siap dijemput dan tugaskan driver.</li></ol><button class="button" data-action="guide">Panduan penyiapan admin ${icon('arrow',14)}</button></div></section><section class="card" style="grid-column:1/-1"><div class="card-head"><div><h2>Riwayat aktivitas admin</h2><p class="subtext">Aktivasi, moderasi, verifikasi, dan penugasan driver.</p></div><button class="button link" data-action="audit">Muat riwayat ${icon('refresh',13)}</button></div><div id="audit-content">${empty('Riwayat aktivitas','Klik Muat riwayat untuk melihat 20 perubahan admin terakhir.')}</div></section></div>`;}
function openModal(title,body,actions=''){modal.innerHTML=`<header class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Tutup dialog">${icon('close',20)}</button></header><div class="modal-body">${body}<div class="modal-error" id="modal-error" role="alert"></div></div><footer class="modal-footer"><button class="button" data-action="close-modal">Tutup</button>${actions}</footer>`;if(!modal.open)modal.showModal();}
function detailField(title,value,full=false){return `<div ${full?'class="detail-full"':''}><div class="detail-label">${e(title)}</div><div class="detail-value">${e(value||'—')}</div></div>`;}
function detail(kind,id){const row=cache.get(`${kind}:${id}`);if(!row)return toast('Perbarui data sebelum membuka detail.',true);let fields='',actions='';
  if(kind==='stores'){fields=detailField('Pemilik',row.secondary)+detailField('Email',row.email)+detailField('Produk',number(row.products))+detailField('Pesanan',number(row.orders))+detailField('Alamat',row.address,true);actions=actionButton('store_suspended',row.id,String(!row.is_suspended),row.is_suspended?'Aktifkan UMKM':'Tangguhkan UMKM',!row.is_suspended);}
  if(kind==='users')fields=detailField('Email',row.email)+detailField('Telepon',row.secondary)+detailField('Bergabung',date(row.created_at))+detailField('Login terakhir',date(row.last_sign_in_at));
  if(kind==='products'){fields=detailField('UMKM',row.secondary)+detailField('Kategori',row.category)+detailField('Harga',money(row.amount))+detailField('Ditambahkan',date(row.created_at))+detailField('Deskripsi',row.description,true);actions=actionButton('product_blocked',row.id,String(!row.is_blocked),row.is_blocked?'Pulihkan produk':'Blokir produk',!row.is_blocked);}
  if(kind==='drivers'){fields=detailField('Email',row.email)+detailField('Telepon',row.phone)+detailField('Kendaraan',row.secondary)+detailField('Terdaftar',date(row.created_at));actions=actionButton('driver_active',row.id,String(!row.active),row.active?'Nonaktifkan driver':'Aktifkan driver',row.active);}
  if(kind==='orders'||kind==='transactions'){fields=detailField('Nomor pesanan','#'+row.id.slice(0,8).toUpperCase())+detailField('UMKM',row.secondary)+detailField('Telepon pembeli',row.phone)+detailField('Dibuat',date(row.created_at))+detailField('Pembayaran',`${label(row.payment_method)} · ${label(row.payment_status)}`)+detailField('Driver',row.driver_name||'Belum ditugaskan')+detailField('Alamat pengiriman',row.address,true);
    if(row.status==='ready_for_pickup'&&!row.driver_id&&(row.payment_method==='cod'||row.payment_status==='success'))actions=`<button class="button primary" data-assign="${e(row.id)}">Tugaskan driver</button>`;
    if(['bank','wallet'].includes(row.payment_method)&&['pending','processing'].includes(row.payment_status)&&!['completed','delivered','cancelled','rejected','payment_failed'].includes(row.status))actions+=actionButton('payment_confirm',row.id,null,'Verifikasi pembayaran');
  }
  if(kind==='audit')fields=detailField('Admin',row.secondary)+detailField('Target',row.target_id)+detailField('Nilai',row.value)+detailField('Tanggal',date(row.created_at));
  const items=(kind==='orders'||kind==='transactions')?`<div class="modal-items">${(row.items||[]).map(i=>`<div class="modal-item"><span>${e(i.name)}<small class="muted"> · ${number(i.quantity)}×${i.variant?' '+e(i.variant):''}</small></span><strong>${money(i.price*i.quantity)}</strong></div>`).join('')}</div><div class="modal-totals">${[['Subtotal',row.subtotal],['Ongkos kirim',row.shipping_fee],['Biaya layanan',row.service_fee],['Diskon',-row.discount_amount]].map(([t,v])=>`<div><span>${t}</span><span>${money(v)}</span></div>`).join('')}<div><strong>Total pembayaran</strong><strong>${money(row.amount)}</strong></div></div>`:'';
  openModal('Detail '+({stores:'UMKM',users:'pengguna',products:'produk',drivers:'driver',orders:'pesanan',transactions:'transaksi',audit:'aktivitas'}[kind]),`<div class="modal-person"><span class="avatar">${e(initials(row.name))}</span><div><h3>${e(label(row.name))}</h3><p>${badge(row.status)}</p></div></div><div class="details">${fields}</div>${items}${mode==='demo'?'<div class="demo-hint">Mode contoh · perubahan hanya berlaku pada simulasi ini.</div>':''}`,actions);
}
function actionButton(action,id,value,title,danger=false){return `<button class="button ${danger?'danger':'primary'}" data-confirm="${action}" data-id="${e(id)}" ${value===null?'':`data-value="${e(value)}"`}>${e(title)}</button>`;}
const actionTitles={driver_active:'Ubah status driver',store_suspended:'Ubah status UMKM',product_blocked:'Ubah status produk',payment_confirm:'Konfirmasi pembayaran'};
function confirmAction(action,id,value){const description=action==='driver_active'?(value==='true'?'Driver akan mendapat akses ke tugas pengantaran setelah diaktifkan. Pastikan data dan dokumen driver sudah Anda periksa.':'Driver akan kehilangan akses tugas pengantaran. Driver dengan tugas aktif harus menyelesaikan tugasnya terlebih dahulu.'):action==='store_suspended'?(value==='true'?'Produk UMKM ini akan disembunyikan dari katalog dan pesanan baru akan dihentikan. Pesanan berjalan tetap dapat diproses.':'UMKM dapat menerima pesanan baru dan produknya dapat tampil kembali sesuai ketersediaan.'):action==='product_blocked'?(value==='true'?'Produk akan disembunyikan dari pembeli dan tidak dapat dipesan sampai dipulihkan.':'Produk dapat tampil kembali sesuai ketersediaan toko.'): 'Pastikan dana dengan nominal yang benar sudah benar-benar masuk ke rekening atau dompet pembayaran toko. Konfirmasi ini akan menandai pembayaran sebagai lunas.';
  openModal(actionTitles[action]||'Konfirmasi perubahan',`<p>${e(description)}</p>${mode==='demo'?'<div class="demo-hint">Anda sedang menguji perubahan pada data contoh.</div>':''}`,`<button class="button primary" data-execute="${action}" data-id="${e(id)}" ${value===undefined?'':`data-value="${e(value)}"`}>${action==='payment_confirm'?'Dana sudah diterima':'Ya, simpan perubahan'}</button>`);
}
async function assign(id){openModal('Tugaskan driver',loading());try{const result=await api().list('drivers',{status:'active',limit:100});if(!modal.open)return;openModal('Tugaskan driver',result.rows.length?`<p>Pilih driver aktif yang sedang tersedia. Setelah ditugaskan, status pengantaran mengikuti lokasi dan aktivitas driver.</p><label class="form-field">Driver tersedia<select class="select" id="assign-driver">${result.rows.map(d=>`<option value="${e(d.id)}">${e(d.name)} · ${e(d.secondary)}</option>`).join('')}</select></label><small class="muted">${result.total>100?'Menampilkan 100 driver tersedia pertama.':`${result.total} driver tersedia`}</small>`:empty('Belum ada driver tersedia','Aktifkan akun driver atau tunggu driver menyelesaikan tugasnya.'),result.rows.length?`<button class="button primary" data-execute="assign_driver" data-id="${e(id)}">Tugaskan driver</button>`:'');}catch(error){openModal('Driver belum dapat dimuat',`<p>${e(error.message)}</p>`);}}
function guide(){openModal('Menyiapkan akses admin',`<p>Penyiapan awal dilakukan oleh pemilik proyek Supabase. Gunakan akun email yang sudah terdaftar di aplikasi RasaLokal.</p><ol style="font-size:12px;color:#6e7f94;line-height:1.9"><li>Jalankan migrasi driver dan admin di SQL Editor proyek Supabase. Unduhan berikut berisi tiga migrasi terbaru; skema dasar RasaLokal harus sudah ada.</li><li>Ganti email pada SQL aktivasi di bawah dengan email akun admin, lalu jalankan di SQL Editor.</li><li>Kembali ke situs ini dan masuk dengan email serta kata sandi akun tersebut.</li></ol><a class="button" href="./setup/admin.sql" download>${icon('download',15)}Unduh SQL driver & admin</a><div class="setup-code" style="margin-top:16px">insert into public.marketplace_admins (user_id, active)
select id, true from auth.users
where lower(email) = lower('GANTI_EMAIL_ADMIN')
on conflict (user_id) do update set active = true;</div><p style="font-size:11px;margin-top:13px">Pastikan SQL menghasilkan satu baris. Jika nol, periksa email atau daftarkan akun melalui RasaLokal terlebih dahulu.</p>`);}
async function exportData(kind,button){if(busy)return;busy=true;button.disabled=true;const original=button.innerHTML;button.innerHTML='Menyiapkan CSV…';try{const all=[];for(let page=0;;page+=100){const result=await api().list(kind,{search:current===kind?search:'',status:current===kind?status:'',offset:page,limit:100,period});if(result.total>10000)throw new Error('Laporan melebihi 10.000 baris. Pilih periode yang lebih pendek.');all.push(...result.rows);if(page+100>=result.total)break;}const columns=[['id','ID Pesanan'],['created_at','Tanggal'],['name','Pembeli'],['secondary','UMKM'],['amount','Total (IDR)'],['status','Status Pesanan'],['payment_method','Metode Pembayaran'],['payment_status','Status Pembayaran']];const blob=new Blob([csv(all,columns)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`rasalokal-${kind}-${periodDates(period).end}${mode==='demo'?'-contoh':''}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${number(all.length)} baris berhasil diekspor${mode==='demo'?' (data contoh)':''}.`);}catch(error){toast(error.message,true);}finally{busy=false;button.disabled=false;button.innerHTML=original;}}
async function logout(){if(mode==='live'){try{await live.logout();}catch(error){toast(error.message,true);return;}}sessionStorage.removeItem('rasalokal-admin-demo');demo.reset();modal.close();showLogin();}
function navigate(id,filter=''){search='';status=filter;offset=0;if(location.hash===`#${id}`)void route();else location.hash=id;}
document.addEventListener('click',async event=>{
  const button=event.target.closest('button,a');if(!button)return;
  if(button.dataset.nav){event.preventDefault();navigate(button.dataset.nav);return;}
  if(button.dataset.detail){detail(button.dataset.detail,button.dataset.id);return;}
  if(button.dataset.confirm){confirmAction(button.dataset.confirm,button.dataset.id,button.dataset.value);return;}
  if(button.dataset.assign){void assign(button.dataset.assign);return;}
  if(button.dataset.execute){if(busy)return;busy=true;button.disabled=true;const action=button.dataset.execute;try{const value=action==='assign_driver'?document.querySelector('#assign-driver').value:button.dataset.value??null;await api().action(action,button.dataset.id,value);modal.close();toast(mode==='demo'?'Perubahan contoh berhasil disimpan.':'Perubahan berhasil disimpan.');await route();}catch(error){document.querySelector('#modal-error').textContent=error.message;}finally{busy=false;button.disabled=false;}return;}
  if(button.dataset.export){void exportData(button.dataset.export,button);return;}
  switch(button.dataset.action){
    case 'demo':mode='demo';sessionStorage.setItem('rasalokal-admin-demo','1');renderShell();void route();break;
    case 'logout':void logout();break;
    case 'guide':guide();break;
    case 'refresh':void route();break;
    case 'show-password':{const input=document.querySelector('[name="password"]');input.type=input.type==='password'?'text':'password';button.setAttribute('aria-label',input.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi');break;}
    case 'close-modal':if(!busy)modal.close();break;
    case 'menu':document.querySelector('.sidebar').classList.toggle('open');button.setAttribute('aria-expanded',document.querySelector('.sidebar').classList.contains('open'));break;
    case 'close-menu':document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');break;
    case 'pending-drivers':navigate('drivers','pending');break;
    case 'pending-payments':navigate('transactions','review');break;
    case 'ready-orders':navigate('orders','ready_for_pickup');break;
    case 'previous':offset=Math.max(0,offset-10);void loadTable();break;
    case 'next':offset+=10;void loadTable();break;
    case 'audit':{const target=document.querySelector('#audit-content');target.innerHTML=loading();try{const result=await api().list('audit',{limit:20,period:'year'});if(current==='settings'){remember(result.rows,'audit');target.innerHTML=table('audit',result.rows)+`<p class="chart-note">20 aktivitas terbaru pada tahun ini.</p>`;}}catch(error){target.innerHTML=empty('Riwayat belum dapat dimuat',error.message);}break;}
  }
});
document.addEventListener('submit',async event=>{if(event.target.id!=='login-form')return;event.preventDefault();const form=event.target,submit=form.querySelector('[type="submit"]'),errorBox=document.querySelector('#login-error');submit.disabled=true;submit.textContent='Memeriksa akses…';errorBox.hidden=true;try{await enterLive(await live.login(form.email.value.trim(),form.password.value));}catch(error){if(document.querySelector('#login-error')){errorBox.hidden=false;errorBox.textContent=error.message==='Invalid login credentials'?'Email atau kata sandi tidak sesuai.':error.message;}}finally{if(submit.isConnected){submit.disabled=false;submit.innerHTML=`Masuk ke dashboard ${icon('arrow',16)}`;}}});
let debounce;
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;offset=0;clearTimeout(debounce);debounce=setTimeout(()=>void loadTable(),250);}});
document.addEventListener('change',event=>{if(event.target.id==='status'){status=event.target.value;offset=0;void loadTable();}if(event.target.id==='period'){period=event.target.value;offset=0;void route();}});
window.addEventListener('hashchange',()=>{if(mode)void route();});
modal.addEventListener('cancel',event=>{if(busy)event.preventDefault();});
setInterval(()=>{if(mode==='live'&&current==='dashboard'&&!document.hidden&&!modal.open&&!busy)void route();},60000);
async function boot(){if(sessionStorage.getItem('rasalokal-admin-demo')){mode='demo';renderShell();await route();return;}try{await enterLive(await live.session());}catch(error){showLogin(error.message);}}
void boot();
